begin;
insert into public.business_settings(key,value) values('matatu_play_rules','{"minimum_playback_percentage":0.8,"cooldown_minutes":60,"daily_play_limit":10,"fixed_reward_kes":40,"demo_duration_seconds":12}') on conflict(key) do nothing;
create type public.playback_session_status as enum('PLAYING','STOPPED','QUALIFIED','NOT_QUALIFIED','FLAGGED');
create type public.trip_session_status as enum('ACTIVE','COMPLETED');
create table public.playback_sessions(id uuid primary key default gen_random_uuid(),campaign_participation_id uuid not null references public.campaign_participations(id) on delete restrict,matatu_id uuid not null references public.matatus(id) on delete restrict,song_id uuid not null references public.songs(id) on delete restrict,started_at timestamptz not null default now(),ended_at timestamptz,playback_position_seconds integer not null default 0,completion_percentage numeric(5,2) not null default 0,status public.playback_session_status not null default 'PLAYING',rejection_reason text,play_event_id uuid references public.play_events(id) on delete set null,created_at timestamptz not null default now());
create unique index one_active_matatu_playback on public.playback_sessions(matatu_id) where status='PLAYING';
create table public.trip_sessions(id uuid primary key default gen_random_uuid(),matatu_id uuid not null references public.matatus(id) on delete cascade,started_by_profile_id uuid not null references public.profiles(id) on delete restrict,route_label text,external_source text,external_reference text,status public.trip_session_status not null default 'ACTIVE',started_at timestamptz not null default now(),ended_at timestamptz,summary jsonb not null default '{}'::jsonb);
create unique index one_active_matatu_trip on public.trip_sessions(matatu_id) where status='ACTIVE';
alter table public.playback_sessions enable row level security;alter table public.trip_sessions enable row level security;
create policy playback_crew_read on public.playback_sessions for select to authenticated using(public.can_manage_matatu(matatu_id) or public.is_admin());create policy trips_crew_read on public.trip_sessions for select to authenticated using(public.can_manage_matatu(matatu_id) or public.is_admin());grant select on public.playback_sessions,public.trip_sessions to authenticated;
create policy requests_target_crew_read on public.song_requests for select to authenticated using((target_type='MATATU' and public.can_manage_matatu(target_id)) or requester_profile_id=public.current_profile_id());
create policy requests_target_crew_update on public.song_requests for update to authenticated using(target_type='MATATU' and public.can_manage_matatu(target_id)) with check(target_type='MATATU' and public.can_manage_matatu(target_id) and status in('SEEN','PLAYED','DECLINED'));
grant update(status) on public.song_requests to authenticated;
create function public.matatu_campaign_decision(p_campaign_id uuid,p_accept boolean) returns uuid language plpgsql security definer set search_path='' as $$declare vehicle uuid;part uuid;begin select m.matatu_id into vehicle from public.matatu_crew_memberships m where m.profile_id=public.current_profile_id() limit 1;if vehicle is null then raise exception 'MATATU_NOT_AUTHORIZED';end if;if not exists(select 1 from public.campaigns c join public.campaign_participant_types t on t.campaign_id=c.id where c.id=p_campaign_id and c.status='ACTIVE' and t.participant_type='MATATU' and current_date between c.start_date and c.end_date) then raise exception 'CAMPAIGN_NOT_ELIGIBLE';end if;insert into public.campaign_participations(campaign_id,participant_type,matatu_id,status,accepted_at,rejected_at) values(p_campaign_id,'MATATU',vehicle,case when p_accept then 'ACCEPTED' else 'REJECTED' end,case when p_accept then now() end,case when not p_accept then now() end) on conflict(campaign_id,dj_profile_id,matatu_id) do update set status=excluded.status,accepted_at=excluded.accepted_at,rejected_at=excluded.rejected_at returning id into part;return part;end$$;
create function public.start_matatu_playback(p_participation_id uuid) returns uuid language plpgsql security definer set search_path='' as $$declare p public.campaign_participations;c public.campaigns;s uuid;begin select * into p from public.campaign_participations where id=p_participation_id and matatu_id is not null and public.can_manage_matatu(matatu_id);if p.id is null or p.status not in('ACCEPTED','ACTIVE') then raise exception 'PARTICIPATION_REQUIRED';end if;select * into c from public.campaigns where id=p.campaign_id and status='ACTIVE' and current_date between start_date and end_date;if c.id is null then raise exception 'CAMPAIGN_NOT_ACTIVE';end if;insert into public.playback_sessions(campaign_participation_id,matatu_id,song_id) values(p.id,p.matatu_id,c.song_id) returning id into s;update public.campaign_participations set status='ACTIVE' where id=p.id;return s;end$$;
create function public.finish_matatu_playback(p_session_id uuid,p_position_seconds integer) returns jsonb language plpgsql security definer set search_path='' as $$declare s public.playback_sessions;p public.campaign_participations;c public.campaigns;rule jsonb;effective_duration integer;elapsed integer;pct numeric;reward numeric;reason text;event_id uuid;campaign_wallet uuid;crew_wallet uuid;balance numeric;today_count integer;begin select * into s from public.playback_sessions where id=p_session_id and status='PLAYING' and public.can_manage_matatu(matatu_id) for update;if s.id is null then select status,play_event_id into reason,event_id from public.playback_sessions where id=p_session_id;return jsonb_build_object('status',coalesce(reason,'NOT_FOUND'),'play_event_id',event_id);end if;select * into p from public.campaign_participations where id=s.campaign_participation_id;select * into c from public.campaigns where id=p.campaign_id;select value into rule from public.business_settings where key='matatu_play_rules';select least(coalesce(duration_seconds,999999),(rule->>'demo_duration_seconds')::integer) into effective_duration from public.songs where id=s.song_id;elapsed=extract(epoch from(now()-s.started_at))::integer;pct=least(100,round((p_position_seconds::numeric/nullif(effective_duration,0))*100,2));reward=(rule->>'fixed_reward_kes')::numeric;
if p_position_seconds>elapsed+2 then reason='IMPOSSIBLE_PLAYBACK_TIME';elsif c.status<>'ACTIVE' or current_date not between c.start_date and c.end_date then reason='CAMPAIGN_NOT_ACTIVE';elsif pct<(rule->>'minimum_playback_percentage')::numeric*100 then reason='MINIMUM_PLAYBACK';elsif exists(select 1 from public.play_events e where e.campaign_participation_id=p.id and e.qualification_status='QUALIFIED' and e.started_at>now()-make_interval(mins=>(rule->>'cooldown_minutes')::integer)) then reason='COOLDOWN';else select count(*) into today_count from public.play_events e where e.campaign_participation_id=p.id and e.qualification_status='QUALIFIED' and e.started_at>=current_date;if today_count>=(rule->>'daily_play_limit')::integer then reason='DAILY_LIMIT';end if;end if;
if reason is null then select id into campaign_wallet from public.wallets where campaign_id=c.id and wallet_type='CAMPAIGN_BUDGET';select id into crew_wallet from public.wallets where profile_id=public.current_profile_id() and wallet_type='EARNINGS';select coalesce(sum(case when direction='CREDIT' then amount else -amount end)filter(where status='POSTED'),0) into balance from public.ledger_transactions where wallet_id=campaign_wallet;if balance<reward then reason='BUDGET_EXHAUSTED';end if;end if;
insert into public.play_events(song_id,campaign_id,campaign_participation_id,source_type,source_id,started_at,ended_at,duration_seconds,verification_status,verification_method,qualification_status,qualified_at,metadata) values(s.song_id,c.id,p.id,'MATATU',s.matatu_id,s.started_at,now(),p_position_seconds,case when reason='IMPOSSIBLE_PLAYBACK_TIME' then 'FLAGGED' else 'VERIFIED' end,'SAUTI_PLAYER',case when reason is null then 'QUALIFIED' when reason='IMPOSSIBLE_PLAYBACK_TIME' then 'REVIEW_REQUIRED' else 'DISQUALIFIED' end,case when reason is null then now() end,jsonb_build_object('completion_percentage',pct,'rejection_reason',reason,'server_elapsed_seconds',elapsed)) returning id into event_id;
if reason is null then insert into public.ledger_transactions(wallet_id,transaction_type,direction,amount,currency,reference_type,reference_id,description,status,idempotency_key,posted_at) values(campaign_wallet,'PARTICIPANT_EARNING','DEBIT',reward,'KES','play_event',event_id,'Qualified Matatu campaign play','POSTED','matatu-play-debit-'||event_id,now()),(crew_wallet,'PARTICIPANT_EARNING','CREDIT',reward,'KES','play_event',event_id,'Qualified Matatu campaign play','POSTED','matatu-play-credit-'||event_id,now());update public.campaign_participations set earned_amount=earned_amount+reward,qualified_play_count=qualified_play_count+1,last_qualified_play_at=now() where id=p.id;end if;update public.playback_sessions set ended_at=now(),playback_position_seconds=p_position_seconds,completion_percentage=pct,status=case when reason is null then 'QUALIFIED' when reason='IMPOSSIBLE_PLAYBACK_TIME' then 'FLAGGED' else 'NOT_QUALIFIED' end,rejection_reason=reason,play_event_id=event_id where id=s.id;return jsonb_build_object('status',case when reason is null then 'QUALIFIED' else 'NOT_QUALIFIED' end,'reason',reason,'earned',case when reason is null then reward else 0 end,'percentage',pct,'play_event_id',event_id);end$$;
grant execute on function public.matatu_campaign_decision(uuid,boolean),public.start_matatu_playback(uuid),public.finish_matatu_playback(uuid,integer) to authenticated;
commit;
